/* TTS loading state: <use id="spinner"> from TTSStateManager (control panel + play button) */
#tolkie-iframe-tts-control-btn svg #spinner,
#tolkie-iframe-tts-play-btn svg #spinner {
    box-sizing: border-box;
    stroke: var(--tolkie-primary-color);
    stroke-width: 3px;
    -webkit-transform-origin: 50%;
    transform-origin: 50%;
    -webkit-animation: tolkie-tts-spinner-line 1.6s cubic-bezier(0.4, 0, 0.2, 1) infinite,
        tolkie-tts-spinner-rotate 1.6s linear infinite;
    animation: tolkie-tts-spinner-line 1.6s cubic-bezier(0.4, 0, 0.2, 1) infinite,
        tolkie-tts-spinner-rotate 1.6s linear infinite;
}

#tolkie-iframe-tts-control-btn.tolkie-iframe-tts-active-border svg #spinner {
    stroke: #fff;
}

