.tolkie-iframe-highlight-element[data-high-contrast-border="true"]::after {
    box-shadow: 0 0 0 2px var(--dark-green-color);
}

.tolkie-iframe-highlight-sentence-word[data-high-contrast-border="true"]::after,
.tolkie-iframe-highlight-element[data-high-contrast-border="true"]::after {
