/* Loading label + dots */
.tolkie-iframe-loading-container {
    height: 30vh;
    display: flex;
    justify-content: center;
    align-items: center;
}

.tolkie-iframe-loading-container.absolute-center {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.tolkie-iframe-loading-label-row {
    display: flex;
    flex-direction: row;
    align-items: baseline;
    justify-content: center;
    gap: 0.3em;
    color: var(--tolkie-primary-color);
    padding: 50px 0;
}

.tolkie-iframe-loading-dots {
    display: inline-flex;
    align-items: center;
    gap: 0.2em;
}

.tolkie-iframe-loading-dot {
    display: inline-block;
    width: 0.4em;
    height: 0.4em;
    border-radius: 50%;
    background: currentColor;
    -webkit-animation: tolkie-loading-dot-pulse 0.55s ease-in-out infinite;
    animation: tolkie-loading-dot-pulse 0.55s ease-in-out infinite;
}

.tolkie-iframe-loading-dot:nth-child(1) {
    -webkit-animation-delay: 0s;
    animation-delay: 0s;
}

.tolkie-iframe-loading-dot:nth-child(2) {
    -webkit-animation-delay: 0.12s;
    animation-delay: 0.12s;
}

.tolkie-iframe-loading-dot:nth-child(3) {
    -webkit-animation-delay: 0.24s;
    animation-delay: 0.24s;
}

@-webkit-keyframes tolkie-loading-dot-pulse {

    0%,
    100% {
        opacity: 0.35;
        -webkit-transform: translateY(0);
        transform: translateY(0);
    }

    50% {
        opacity: 1;
        -webkit-transform: translateY(-0.12em);
        transform: translateY(-0.12em);
    }
}

@keyframes tolkie-loading-dot-pulse {

    0%,
    100% {
        opacity: 0.35;
        -webkit-transform: translateY(0);
        transform: translateY(0);
    }

    50% {
        opacity: 1;
        -webkit-transform: translateY(-0.12em);
        transform: translateY(-0.12em);
    }
}

.tolkie-iframe-loading-container.tolkie-iframe-loading-animation-paused .tolkie-iframe-loading-dot,
.tolkie-iframe-loading-animation-paused .tolkie-iframe-loading-dot {
    -webkit-animation: none;
    animation: none;
    opacity: 1;
    -webkit-transform: translateY(0);
    transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {

    .tolkie-iframe-loading-dot {
        -webkit-animation: none;
        animation: none;
        opacity: 1;
        -webkit-transform: none;
        transform: none;
    }
}

