/* Debug */

.Spacer--debug {
    outline: 1px solid var(--spacer-debug-color);
}

.Spacer--debug::before {
    content: 'Spacer';
    position: absolute;
    top: 0;
    right: 0;
    transform: translate(-4px, -100%);
    font-family: monospace;
    font-size: 10px;
    padding: 0 4px;
    color: white;
    background: var(--spacer-debug-color);
    pointer-events: none;
}

.Logo {
    flex-shrink: 0;

    /* Brand color per scheme: navy in light, white in dark. This is the only
   * --dui-* token with that flip (--dui-color-text-brand stays navy in both
   * schemes) — nearest semantic match until a dedicated logo/brand-mark
   * token ships in @deepl/theme. */
    &.as-color-brand {
        color: var(--dui-color-background-action-brand);
    }

    /* Defers to currentColor from the parent, e.g. always-white on
   * brand-navy chrome. */
    &.as-color-inherit {
        color: inherit;
    }
}

/*
 * Sidebar — V5 navigation rail (deepl/deeplatform/nav-revamp-react).
 * Expanded 256px column ↔ 60px icon-only rail. The width animates on
 * `.is-collapsed`; the icon-only layout (`.is-icon-only`) is applied by the
 * component only after the animation settles, so labels clip away cleanly.
 */

.Sidebar {
    /* stylelint-disable-next-line ecss/component-dimensions -- Sidebar is a layout component; the expanded/collapsed column widths are its identity (256px keeps the rail above icon-hiding thresholds, 60px centres a 32px icon button on the expanded icon column) */
    width: 256px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    background: var(--dui-color-background-surface);
    border-inline-end: var(--dui-spacing-px) solid var(--dui-color-border-default);
    /* Clips full-width content while the width animates. */
    /* stylelint-disable-next-line ecss/overflow-hidden -- required for the width animation to clip labels instead of popping layouts */
    overflow: hidden;
    font-size: var(--dui-typography-body-s-font-size);
    line-height: var(--dui-typography-body-s-line-height);
    transition: width 0.2s ease-in-out;
}

.Sidebar.is-collapsed {
    width: 60px;
}

/* Once icon-only, keep overflow visible so the rail's tooltips and flyouts
   aren't clipped (the short rail doesn't need to scroll). */
.Sidebar.is-icon-only {
    overflow: visible;
}

.Sidebar .SidebarHeader {
    display: flex;
    align-items: center;
    padding: var(--dui-spacing-l) var(--dui-spacing-xl) var(--dui-spacing-m);
}

.Sidebar .SidebarNav {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
}

.Sidebar .SidebarNav .__scroll {
    display: flex;
    flex-direction: column;
    gap: var(--dui-spacing-xs);
    height: 100%;
    overflow-y: auto;
    padding-inline: var(--dui-spacing-m);
}

.Sidebar.is-icon-only .SidebarNav .__scroll {
    overflow: visible;
}

.Sidebar .SidebarFooter {
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    gap: var(--dui-spacing-xs);
    padding: var(--dui-spacing-m);
}

/* ─── Rows ──────────────────────────────────────────────────── */

.Sidebar .SidebarItem {
    display: flex;
    align-items: center;
    gap: var(--dui-spacing-m);
    min-height: var(--dui-spacing-4xl);
    padding-block: var(--dui-spacing-s);
    padding-inline: var(--dui-spacing-l);
    border: 0;
    border-radius: var(--dui-radius-m);
    background: none;
    color: var(--dui-color-text-default);
    font: inherit;
    font-weight: var(--dui-typography-font-weight-regular);
    text-align: start;
    text-decoration: none;
    white-space: nowrap;
    cursor: pointer;

    &:hover {
        background: var(--dui-color-background-action-ghost-hover);
    }

    &:focus-visible {
        outline: var(--dui-spacing-xs) solid var(--dui-color-border-focus);
        outline-offset: calc(-1 * var(--dui-spacing-xs));
    }

    /* Blue "you are on this page/section" state (wayfinding). */
    &.is-active {
        background: var(--dui-color-background-action-active);
        color: var(--dui-color-text-action-active);
        font-weight: var(--dui-typography-font-weight-semibold);
    }

    /* Neutral gray pressed state for menu/flyout triggers — a menu row, not
     the blue page state. */
    &.is-current {
        background: var(--dui-color-background-action-ghost-pressed);
        color: var(--dui-color-text-default);
    }
}

/* Foldable wrapper stretches its trigger to the full column, the way plain
   items already stretch as direct flex children of the scroll area. Without a
   layout context here the nested trigger button shrinks to its content, so its
   pill and trailing chevron stop short of the edge. A column flex hands the
   default stretch alignment down to the button. */
.Sidebar .SidebarFoldable {
    display: flex;
    flex-direction: column;
}

/* Trailing chevron on inline foldable triggers; rotates 180° clockwise in
   sync with the disclosure slide. */
.Sidebar .SidebarItem .__chevron {
    display: flex;
    align-items: center;
    margin-inline-start: auto;
    color: var(--dui-color-text-muted);
    transition: transform 0.2s ease-out;
}

.Sidebar .SidebarItem[aria-expanded='true'] .__chevron {
    transform: rotate(-180deg);
}

/* Icon-only rail: full-width rows with the same 12px padding as expanded, so
   a collapsed item reads as an expanded button minus its label — identical
   margins, icon column, and pill highlight. The label text node hides via
   font-size: 0 (keeps the SVG icon visible for any children shape). */
.Sidebar.is-icon-only .SidebarItem {
    display: flex;
    justify-content: center;
    gap: 0;
    font-size: 0;
}

.Sidebar.is-icon-only .SidebarItem .__chevron {
    display: none;
}

/* ─── Inline disclosure (foldable) ──────────────────────────── */

/* The grid row transitions 0fr→1fr, sliding the children to their natural
   height — no max-height guess. */
.Sidebar .SidebarFoldable-disclosure {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows 0.2s ease-out;
}

.Sidebar .SidebarFoldable-disclosure.is-open {
    grid-template-rows: 1fr;
}

.Sidebar .SidebarFoldable-disclosure .__clip {
    /* stylelint-disable-next-line ecss/overflow-hidden -- what lets the grid row collapse to zero during the slide */
    overflow: hidden;
}

/* Children indented with a vertical guide line aligned to the parent icon's
   centre: item padding-inline (12px) + half the 20px "small" icon. */
.Sidebar .SidebarFoldable-disclosure .__children {
    display: flex;
    flex-direction: column;
    margin-block-start: var(--dui-spacing-xs);
    margin-inline-start: calc(var(--dui-spacing-l) + var(--dui-spacing-2xl) / 2);
    padding-inline-start: calc(var(--dui-spacing-s) + var(--dui-spacing-px));
    border-inline-start: var(--dui-spacing-px) solid var(--dui-color-border-default);
}

.Sidebar.is-icon-only .SidebarFoldable-disclosure {
    display: none;
}

/* ─── Sub items ─────────────────────────────────────────────── */

.SidebarSubItem {
    display: flex;
    align-items: center;
    gap: var(--dui-spacing-m);
    min-height: var(--dui-spacing-4xl);
    padding-block: var(--dui-spacing-s);
    padding-inline: var(--dui-spacing-l);
    border: 0;
    border-radius: var(--dui-radius-m);
    background: none;
    color: var(--dui-color-text-default);
    font: inherit;
    font-weight: var(--dui-typography-font-weight-regular);
    text-align: start;
    text-decoration: none;
    cursor: pointer;

    &:hover {
        background: var(--dui-color-background-action-ghost-hover);
    }

    &:focus-visible {
        outline: var(--dui-spacing-xs) solid var(--dui-color-border-focus);
        outline-offset: calc(-1 * var(--dui-spacing-xs));
    }

    /* Neutral gray "current menu row" state — deliberately not the blue page
     state: gray = menu/flyout row, blue = page/section (wayfinding). */
    &.is-current {
        background: var(--dui-color-background-action-ghost-pressed);
        color: var(--dui-color-text-default);
        font-weight: var(--dui-typography-font-weight-semibold);
    }
}

/* ─── Flyout body (collapsed rail + bottom zone) ────────────── */

.SidebarFlyout {
    /* Flyout identity width from the V5 handoff — wide enough for typical
     two-word sub-item labels; no --dui-* step exists at 176px. */
    min-width: 176px;
    padding-block: var(--dui-spacing-m);
    display: flex;
    flex-direction: column;
}

.SidebarFlyout .__label {
    margin: 0;
    padding: var(--dui-spacing-s) var(--dui-spacing-l) 0.375rem;
    font-size: var(--dui-typography-body-xs-font-size);
    line-height: var(--dui-typography-body-xs-line-height);
    color: var(--dui-color-text-muted);
}

/* ─── Collapse control ──────────────────────────────────────── */

.Sidebar .SidebarCollapseButton {
    align-self: flex-end;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--dui-spacing-4xl);
    height: var(--dui-spacing-4xl);
    padding: 0;
    border: 0;
    border-radius: var(--dui-radius-m);
    background: none;
    color: var(--dui-color-text-muted);
    cursor: pointer;

    &:hover {
        background: var(--dui-color-background-action-ghost-hover);
    }

    &:focus-visible {
        outline: var(--dui-spacing-xs) solid var(--dui-color-border-focus);
        outline-offset: calc(-1 * var(--dui-spacing-xs));
    }
}

.Sidebar.is-icon-only .SidebarCollapseButton {
    align-self: center;
}

.Sidebar.is-icon-only .SidebarFooter {
    display: flex;
    align-items: center;
}

.Sidebar.is-icon-only .SidebarFooter>* {
    width: 100%;
}

/*
 * Container — single-purpose primitive that declares a container-query
 * boundary named `component`. Pair with `<Spacer scope="component">` to
 * drive a descendant Spacer's responsive props off this element's inline
 * size instead of the viewport. No visual styling.
 */

.Container {
    container-type: inline-size;
    container-name: component;
}

/* stylelint-disable ecss/selector-filename, plugin/z-index-value-constraint -- DS-wide debug overlay (DUI-1734). The selectors target the cross-cutting `data-dui-component` attribute emitted by every visual DS component (see packages/ui/docs/component-taxonomy.md), so the per-component-file selector convention does not apply. The z-index value on the corner label is intentionally above the documented `--dui-z-index-*` scale because the debug overlay must paint above every real UI layer including tooltips. */

/*
 * DS-wide debug overlay (DUI-1734).
 *
 * Activated by DesignSystemProvider when `debug={true}`. The provider sets
 * `data-dui-debug="true"` on <html>; every rule below is gated on that
 * attribute, so when debug is off there is zero visual change.
 *
 * Layout: a 1px dashed outline on every element carrying
 * `data-dui-component`, plus a small absolutely-positioned name-label tag
 * in the top-left corner showing the component's name. Container-like
 * components (Card, Dialog, Popover, Layout, SidePanel, Navbar, Tabs,
 * Accordion, DropdownMenu, Container) get a larger more prominent label.
 *
 * Colour palette is keyed by the taxonomy category from
 * `packages/ui/docs/component-taxonomy.md`: primitive (cyan),
 * native-wrapper (amber), composite (purple), component (green). The
 * per-component-to-category mapping is hard-coded as attribute-selector
 * lists below — the category set is closed (4 buckets) and stable. The
 * source of truth for each component's category is its Storybook story
 * (`parameters.dui.category` + `dui:category:*` tag), so keep these lists
 * in sync with the stories when a new component lands.
 *
 * Anything not listed below falls through to a neutral "uncategorised"
 * red, making the gap visible during development.
 */

[data-dui-debug] {
    /* Debug palette — picked to be high-contrast on both light and dark
   * surfaces. Tuned to be readable but not so saturated that it overwhelms
   * the real UI underneath. */
    --dui-debug-primitive: #06b6d4;
    /* cyan-500   — layout glue */
    --dui-debug-native-wrapper: #f59e0b;
    /* amber-500 — native elements */
    --dui-debug-composite: #a855f7;
    /* purple-500 — orchestration */
    --dui-debug-component: #10b981;
    /* emerald-500 — fully-fledged components */
    --dui-debug-uncategorised: #ef4444;
    /* red-500   — missing from mapping */

    /* Default — everything starts here, then category rules override. */
    --dui-debug-color: var(--dui-debug-uncategorised);
}

/* ---------- Outline + label scaffolding ------------------------------- */

[data-dui-debug] [data-dui-component] {
    outline: 1px dashed var(--dui-debug-color);
    outline-offset: -1px;
    position: relative;
}

/* The corner name-label. `attr(data-dui-component)` reads the component name
 * directly from the DOM, so we don't have to spell every component twice. */
[data-dui-debug] [data-dui-component]::before {
    content: attr(data-dui-component);
    position: absolute;
    top: 0;
    left: 0;
    z-index: 2147483646;
    /* one below the highest reserved overlay layer */
    padding: 1px 4px;
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    font-size: 9px;
    line-height: 1.2;
    font-weight: 500;
    color: white;
    background: var(--dui-debug-color);
    pointer-events: none;
    letter-spacing: 0.02em;
    text-transform: none;
    white-space: nowrap;
}

/* Container components — larger, more prominent label so structural pieces
 * stand out from leaf components in a dense screen. Per the ticket: the
 * larger structural components.
 *
 * NB: these still inherit their category colour from the rules below.
 */
[data-dui-debug] [data-dui-component='Card']::before,
[data-dui-debug] [data-dui-component='Dialog']::before,
[data-dui-debug] [data-dui-component='Popover']::before,
[data-dui-debug] [data-dui-component='Layout']::before,
[data-dui-debug] [data-dui-component='Sidebar']::before,
[data-dui-debug] [data-dui-component='SidePanel']::before,
[data-dui-debug] [data-dui-component='Navbar']::before,
[data-dui-debug] [data-dui-component='Tabs']::before,
[data-dui-debug] [data-dui-component='Accordion']::before,
[data-dui-debug] [data-dui-component='DropdownMenu']::before,
[data-dui-debug] [data-dui-component='Container']::before {
    padding: 2px 6px;
    font-size: 10px;
    font-weight: 600;
}

/* ---------- Category colour mapping ----------------------------------- *
 * Approach (b) from the ticket: hard-code component-to-category mapping
 * here. Keep these lists in sync with each component's Storybook meta —
 * `parameters.dui.category` is the source of truth.
 * --------------------------------------------------------------------- */

/* Primitive — layout glue / scaffolding. */
[data-dui-debug] [data-dui-component='Container'],
[data-dui-debug] [data-dui-component='Spacer'] {
    --dui-debug-color: var(--dui-debug-primitive);
}

/* Native wrapper — preserves a real native HTML element for its
 * irreplaceable behaviour (form participation, IME, autofill, etc). */
[data-dui-debug] [data-dui-component='Button'],
[data-dui-debug] [data-dui-component='Textarea'],
[data-dui-debug] [data-dui-component='Textfield'] {
    --dui-debug-color: var(--dui-debug-native-wrapper);
}

/* Composite — orchestrates standalone components, no concept of its own. */
[data-dui-debug] [data-dui-component='AvatarGroup'],
[data-dui-debug] [data-dui-component='ButtonGroup'],
[data-dui-debug] [data-dui-component='DataTable'],
[data-dui-debug] [data-dui-component='RadioGroup'],
[data-dui-debug] [data-dui-component='ToggleGroup'] {
    --dui-debug-color: var(--dui-debug-composite);
}

/* Component — the default, fully-fledged DS components. */
[data-dui-debug] [data-dui-component='Accordion'],
[data-dui-debug] [data-dui-component='Alert'],
[data-dui-debug] [data-dui-component='Avatar'],
[data-dui-debug] [data-dui-component='Badge'],
[data-dui-debug] [data-dui-component='Caption'],
[data-dui-debug] [data-dui-component='Card'],
[data-dui-debug] [data-dui-component='Checkbox'],
[data-dui-debug] [data-dui-component='Collapsible'],
[data-dui-debug] [data-dui-component='Dialog'],
[data-dui-debug] [data-dui-component='Divider'],
[data-dui-debug] [data-dui-component='DropdownMenu'],
[data-dui-debug] [data-dui-component='Frame'],
[data-dui-debug] [data-dui-component='Icon'],
[data-dui-debug] [data-dui-component='Label'],
[data-dui-debug] [data-dui-component='Layout'],
[data-dui-debug] [data-dui-component='LoadingIndicator'],
[data-dui-debug] [data-dui-component='Logo'],
[data-dui-debug] [data-dui-component='Navbar'],
[data-dui-debug] [data-dui-component='Popover'],
[data-dui-debug] [data-dui-component='ProgressBar'],
[data-dui-debug] [data-dui-component='Select'],
[data-dui-debug] [data-dui-component='Sidebar'],
[data-dui-debug] [data-dui-component='SidePanel'],
[data-dui-debug] [data-dui-component='Switch'],
[data-dui-debug] [data-dui-component='Table'],
[data-dui-debug] [data-dui-component='Tabs'],
[data-dui-debug] [data-dui-component='Tag'],
[data-dui-debug] [data-dui-component='Text'],
[data-dui-debug] [data-dui-component='Toast'],
[data-dui-debug] [data-dui-component='Tooltip'],
[data-dui-debug] [data-dui-component='VideoPlayer'] {
    --dui-debug-color: var(--dui-debug-component);
}

@keyframes dl-alert-fly-in {
    from {
        transform: translateX(100px);
        opacity: 0;
    }

    to {
        transform: translateX(0);
        opacity: 1;
    }
}

@keyframes dl-alert-fly-out {
    from {
        transform: translateX(0);
        opacity: 1;
    }

    to {
        transform: translateX(100px);
        opacity: 0;
    }
}

.dl-alert-container {
    max-width: 446px;
    box-sizing: border-box;
    box-shadow: 0px 4px 16px rgba(0, 0, 0, 0.37);
    border-radius: 6px;
}

.dl-alert-container.dl-visible {
    animation: dl-alert-fly-in 1000ms ease;
}

.dl-alert-container.dl-exiting {
    animation: dl-alert-fly-out 1000ms ease forwards;
}

.dl-error-session-id {
    margin-top: 8px;
    font-size: 12px;
    word-break: break-all;
}

.dl-error-link-container .link {
    margin-top: 16px;
    text-decoration: underline;
    cursor: pointer;
    background: none;
    border: none;
    padding: 0;
    font: inherit;
    color: inherit;
    text-align: left;
}

.dl-anonymous-limit-exceeded {
    position: relative;
    min-height: 250px;
    color: #ffffff;
    background-image: url("../images/graphics/popup-bg.svg");
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center;
}

.dl-anonymous-limit-exceeded.small {
    width: 334px;
    background-image: url("../images/graphics/popup-bg-small.svg");
}

.dl-anonymous-limit-exceeded .actions {
    display: flex;
    justify-content: flex-end;
    align-items: flex-start;
    gap: 8px;
    align-self: stretch;
    padding: 0px 32px 19px 0px;
}

